AS $function$
DECLARE
    new_session_log_id INT;
    round_data jsonb;
    new_round_log_id INT;
    exercise_log_data jsonb;
    v_user_id UUID := auth.uid();
    v_session_id INT;
    v_created_log jsonb;
BEGIN
    v_session_id := (session_log_data->>'session_id')::int;

    -- Verify that the user owns the original session
    IF NOT EXISTS (
        SELECT 1
        FROM public.sessions s
        JOIN public.programs p ON s.program_id = p.id
        WHERE s.id = v_session_id AND p.user_id = v_user_id
    ) THEN
        RAISE EXCEPTION 'Session not found or access denied';
    END IF;

    -- Insert the main session log
    INSERT INTO public.session_logs (user_id, session_id, started_at, ended_at)
    VALUES (
        v_user_id,
        v_session_id,
        (session_log_data->>'started_at')::timestamptz,
        (session_log_data->>'ended_at')::timestamptz
    )
    RETURNING id INTO new_session_log_id;

    -- Loop through rounds
    FOR round_data IN SELECT * FROM jsonb_array_elements(session_log_data->'rounds')
    LOOP
        -- Insert the round log
        INSERT INTO public.round_logs (session_log_id, round_number)
        VALUES (
            new_session_log_id,
            (round_data->>'round_number')::int
        )
        RETURNING id INTO new_round_log_id;

        -- Loop through exercise logs in the round
        FOR exercise_log_data IN SELECT * FROM jsonb_array_elements(round_data->'exercises')
        LOOP
            -- Insert the exercise log
            INSERT INTO public.exercises_logs (round_log_id, session_exercise_id, performance)
            VALUES (
                new_round_log_id,
                (exercise_log_data->>'session_exercise_id')::int,
                exercise_log_data
            );
        END LOOP;
    END LOOP;

    -- Fetch and build the complete SessionLog object to return
    SELECT
        jsonb_build_object(
            'id', sl.id,
            'session_id', sl.session_id,
            'started_at', sl.started_at,
            'ended_at', sl.ended_at,
            'type', s.type, -- For SessionLog deserialization
            'rounds', COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'id', rl.id,
                        'round_number', rl.round_number,
                        'exercises', COALESCE((
                            SELECT jsonb_agg(
                                -- The 'performance' object from the table is the ExerciseLog itself
                                el.performance || jsonb_build_object('type', s.type)
                            )
                            FROM public.exercises_logs el
                            WHERE el.round_log_id = rl.id
                        ), '[]'::jsonb)
                    ) ORDER BY rl.round_number
                )
                FROM public.round_logs rl
                WHERE rl.session_log_id = sl.id
            ), '[]'::jsonb)
        )
    INTO v_created_log
    FROM public.session_logs sl
    JOIN public.sessions s ON sl.session_id = s.id
    WHERE sl.id = new_session_log_id;

    -- Return the created log directly for consistency
    RETURN v_created_log;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_program(p_program_id integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    deleted_id INT;
BEGIN
    DELETE FROM programs
    WHERE id = p_program_id AND user_id = auth.uid()
    RETURNING id INTO deleted_id;

    IF deleted_id IS NULL THEN
        RAISE EXCEPTION 'Program not found or access denied';
    END IF;

    RETURN deleted_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_session_from_program(p_session_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_program_id INT;
    v_user_id UUID := auth.uid();
    session_count INT;
BEGIN
    -- Find the program_id for the session to be deleted and verify ownership
    SELECT program_id INTO v_program_id
    FROM sessions s
    JOIN programs p ON s.program_id = p.id
    WHERE s.id = p_session_id AND p.user_id = v_user_id;

    IF v_program_id IS NULL THEN
        RAISE EXCEPTION 'Session not found or access denied';
    END IF;

    -- Check if it's the last session in the program
    SELECT COUNT(*) INTO session_count
    FROM sessions
    WHERE program_id = v_program_id;

    IF session_count <= 1 THEN
        RAISE EXCEPTION 'Cannot delete the last session of a program.';
    END IF;

    -- Delete the session (cascades to session_exercises and exercise_progressions)
    DELETE FROM sessions WHERE id = p_session_id;

    -- Re-order the remaining sessions
    WITH ranked_sessions AS (
        SELECT
            id,
            ROW_NUMBER() OVER (ORDER BY order_in_program) as new_order
        FROM sessions
        WHERE program_id = v_program_id
    )
    UPDATE sessions s
    SET order_in_program = rs.new_order
    FROM ranked_sessions rs
    WHERE s.id = rs.id;

    -- Return the complete updated program data
    RETURN (
       SELECT get_full_program_by_id(v_program_id)
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_user_account()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- First, delete the user's profile from the public.profiles table
  delete from public.profiles where id = auth.uid();

  -- Then, delete the user from the auth.users table
  delete from auth.users where id = auth.uid();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_full_session_by_id(p_session_id integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
SELECT
    jsonb_strip_nulls(
        jsonb_build_object(
            'id', s.id,
            'program_id', s.program_id,
            'order_in_program', s.order_in_program,
            'name', s.name,
            'session_type', s.type,
            'session_style', s.style,
            'parameters', s.parameters,
            'exercises', COALESCE(
                (
                    SELECT
                        jsonb_agg(
                            jsonb_build_object(
                                'id', se.id,
                                'exercise_id', se.exercise_id,
                                'name', e.name,
                                'order_in_session', se.order_in_session,
                                'template_parameters', se.parameters->'template',
                                'objective_parameters', se.parameters->'objective'
                            ) ORDER BY se.order_in_session
                        )
                    FROM public.session_exercises se
                    JOIN public.exercises e ON se.exercise_id = e.id
                    WHERE se.session_id = s.id
                ),
                '[]'::jsonb
            )
        )
    )
FROM
    public.sessions s
WHERE
    s.id = p_session_id;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_programs(page_number integer, page_size integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
BEGIN
    RETURN (
        SELECT jsonb_agg(program_json)
        FROM (
            SELECT jsonb_build_object(
                'id', p.id,
                'user_id', p.user_id,
                'name', p.name,
                'description', p.description,
                'created_at', p.created_at,
                'updated_at', p.updated_at,
                'is_favorite', EXISTS (
                    SELECT 1
                    FROM favorite_programs fp
                    WHERE fp.program_id = p.id AND fp.user_id = v_user_id
                ),
                'sessions', (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'id', s.id,
                            'name', s.name,
                            'order_in_program', s.order_in_program,
                            'type', s.type,
                            'style', s.style,
                            'exercises', (
                                SELECT jsonb_agg(
                                    jsonb_build_object(
                                        'id', se.id,
                                        'exercise_id', se.exercise_id,
                                        'order_in_session', se.order_in_session,
                                        'exercise', jsonb_build_object('name', e.name),
                                        'parameters', se.parameters,
                                        'progression', (
                                            SELECT jsonb_agg(ep.*)
                                            FROM exercise_progressions ep
                                            WHERE ep.session_exercise_id = se.id
                                        )
                                    )
                                )
                                FROM session_exercises se
                                JOIN exercises e ON se.exercise_id = e.id
                                WHERE se.session_id = s.id
                            )
                        )
                        ||
                        CASE
                            WHEN s.type = 'AMRAP' THEN
                                jsonb_build_object('duration', s.parameters->'duration')
                            WHEN s.type IN ('EMOM', 'HIIT') THEN
                                jsonb_build_object('round_number', s.parameters->'round_number')
                            ELSE
                                '{}'::jsonb
                        END
                    )
                    FROM sessions s
                    WHERE s.program_id = p.id
                )
            ) as program_json
            FROM programs p
            WHERE p.user_id = v_user_id
            ORDER BY p.created_at DESC
            LIMIT page_size
            OFFSET page_number * page_size
        ) as paginated_programs
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_sessions_logs(page_number integer, page_size integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
BEGIN
    RETURN (
        SELECT jsonb_agg(log_json)
        FROM (
            SELECT
                jsonb_build_object(
                    'id', sl.id,
                    'session_id', sl.session_id,
                    'started_at', sl.started_at,
                    'ended_at', sl.ended_at,
                    'type', s.type, -- Crucial for deserialization
                    'rounds', COALESCE((
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'id', rl.id,
                                'round_number', rl.round_number,
                                'exercises', COALESCE((
                                    SELECT jsonb_agg(
                                        -- Inject session type and exercise name for full deserialization
                                        el.performance || jsonb_build_object(
                                            'type', s.type,
                                            'exercise_name', (
                                                SELECT ex.name
                                                FROM public.session_exercises se
                                                JOIN public.exercises ex ON se.exercise_id = ex.id
                                                WHERE se.id = el.session_exercise_id
                                            )
                                        )
                                    )
                                    FROM public.exercises_logs el
                                    WHERE el.round_log_id = rl.id
                                ), '[]'::jsonb)
                            ) ORDER BY rl.round_number
                        )
                        FROM public.round_logs rl
                        WHERE rl.session_log_id = sl.id
                    ), '[]'::jsonb)
                ) as log_json
            FROM public.session_logs sl
            JOIN public.sessions s ON sl.session_id = s.id
            JOIN public.programs p ON s.program_id = p.id
            WHERE p.user_id = v_user_id
            ORDER BY sl.started_at DESC
            LIMIT page_size
            OFFSET page_number * page_size
        ) as paginated_logs
    );
END;
$function$
;

